excels.excel:

EXPORT WITH SHEET="销售退货分析表", HEADER=true,
    MAPPING={"a":"产品名称","b":"销售数量","c":"退货数量","d":"单价","e":"退货金额","f":"退货率","g":"处理方式"},
    FORMAT={"b":"#,##0","c":"#,##0","d":"#,##0.00","e":"#,##0.00","f":"0.00%"},
    FORMULAS={
        E2:'C2*D2',F2:'C2/B2', E3:'C3*D3',F3:'C3/B3', E4:'C4*D4',F4:'C4/B4',
        E5:'C5*D5',F5:'C5/B5', E6:'C6*D6',F6:'C6/B6', E7:'C7*D7',F7:'C7/B7',
        B8:'SUM(B2:B7)',C8:'SUM(C2:C7)',E8:'SUM(E2:E7)',F8:'C8/B8'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
